  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    # map node to index for DSU
    node_to_idx = {node: i for i, node in enumerate(nodes)}
    # build edges with mutual reachability
    edges = []
    for u, v, d in distances:
        if u > v:
            u, v = v, u
        mut = max(core_distance[u], core_distance[v], d)
        edges.append((mut, u, v))
    # sort deterministically: by weight then by endpoint strings
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # DSU (union-find)
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
        return True
    selected = []
    total_weight = 0.0
    for w, u, v in edges:
        iu = node_to_idx[u]
        iv = node_to_idx[v]
        if union(iu, iv):
            selected.append([u, v, w])
            total_weight += w
            if len(selected) == n - 1:
                break
    if len(selected) != n - 1:
        raise ValueError("Disconnected graph: cannot compute MST from given distances")
    return {"mst_edges": selected, "total_weight": total_weight}
